from pathlib import Path
import base64,gzip
root=Path(__file__).resolve().parents[1]
payloads={
'data/capacity/normalized/1401/capacities-biotechnology-zoology.csv': '',
'data/capacity/normalized/1402/capacities-biotechnology-zoology.csv': '',
'data/capacity/normalized/1403/capacities-biotechnology-zoology.csv': '',
'data/capacity/normalized/1404/capacities-biotechnology-zoology.csv': '',
'data/capacity/BIOTECHNOLOGY_ZOOLOGY_REPORT.md': '',
'data/capacity/BIOTECHNOLOGY_ZOOLOGY_SUMMARY.json': '',
}
for rel,data in payloads.items():
    out=root/rel
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_bytes(gzip.decompress(base64.b64decode(data)))
    print("wrote",rel)
